const fetchList = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = connectClient(url);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  const untilDone = new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type !== 'connected') {
        frames.push(frame);
        if (frame.type === 'session_list' || frame.type === 'error') {
          resolve();
        }
        return;
      }
      connected = frame;
      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
    });
  });
  await untilDone;
  return {connected, frames};
};
